plist.dict:
Label
{{ label }}

UserName
{{ user }}

ProgramArguments

  {%- for argument in program_arguments %}
  {{ argument }}
  {%- endfor %}


{%- if !settings.is_empty() %}
EnvironmentVariables

  {%- for (name, value) in settings %}
  {{ name }}
  {{ value }}
  {%- endfor %}

{%- endif %}

RunAtLoad


ExitTimeOut
{{ stop_seconds }}

KeepAlive

  SuccessfulExit
